import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"The cost algebra — signature reference","description":"","frontmatter":{},"headers":[],"relativePath":"eqsat/reference/cost.md","filePath":"vendored/eqsat/reference/cost.md"}`),a={name:`eqsat/reference/cost.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="the-cost-algebra-—-signature-reference" tabindex="-1">The cost algebra — signature reference <a class="header-anchor" href="#the-cost-algebra-—-signature-reference" aria-label="Permalink to “The cost algebra — signature reference”">​</a></h1><p>Signature-level reference for <code>mlopt_core.cost</code>. The conceptual account — why the substrate ships <em>three</em> trust levels of cost — is <a href="/docs/graphopt/explanation/three-costs.html">the three costs</a>; the frozen-name list is <a href="./frozen-api.html">the manifest slice</a>.</p><h2 id="dag-cost-—-the-shared-subtree-honest-price" tabindex="-1"><code>dag_cost</code> — the shared-subtree-honest price <a class="header-anchor" href="#dag-cost-—-the-shared-subtree-honest-price" aria-label="Permalink to “dag_cost — the shared-subtree-honest price”">​</a></h2><div class="language-python"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">dag_cost</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">(</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">term</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;"> cost_fn</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#FFFFFF;--shiki-dark-font-style:italic;--shiki-light:#c13617;--shiki-light-font-style:inherit;"> memo</span><span style="--shiki-dark:#0F0;--shiki-dark-font-style:italic;--shiki-light:#c62739;--shiki-light-font-style:inherit;">=</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">None</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">)</span><span style="--shiki-dark:#FFAA80;--shiki-dark-text-decoration:underline;--shiki-dark-font-style:inherit;--shiki-light:#B31D28;--shiki-light-text-decoration:inherit;--shiki-light-font-style:italic;"> -&gt;</span><span style="--shiki-dark:#C5C5C5;--shiki-light:#005CC5;"> float</span></span></code></pre></div><p>Walks the program <em>graph</em> — a shared subtree is paid once, so a DAG is never billed as a tree. <code>cost_fn</code> is any <code>(term, memo=None) -&gt; float</code> callable (the <code>CostFn</code> port convention); <code>memo</code> threads the shared-subterm cache. This is the <strong>ranking</strong> price: static weights, no tensors executed, no claim.</p><h2 id="the-shipped-models" tabindex="-1">The shipped models <a class="header-anchor" href="#the-shipped-models" aria-label="Permalink to “The shipped models”">​</a></h2><table tabindex="0"><thead><tr><th>family</th><th>names</th><th>shape</th></tr></thead><tbody><tr><td>counting</td><td><code>count_cost(term, memo=None)</code>, <code>flops_cost(term, memo=None)</code></td><td>bare cost fns</td></tr><tr><td>parameters</td><td><code>param_bytes_cost(term, memo=None)</code>, <code>param_bytes_cost_for(source_tensors=None, by_bytes=False)</code></td><td>storage pricing; the <code>_for</code> variant binds the source tensors</td></tr><tr><td>backend-aware</td><td><code>backend_cost(cost_fn, supported_ops) -&gt; CostFn</code></td><td>wraps a base fn — members using ops outside <code>supported_ops</code> price <code>+inf</code>, so search never commits to a form the sink cannot lower</td></tr><tr><td>executor</td><td><code>executor_cost_for(profile=None, *, lowering=&quot;generic&quot;, base=&quot;roofline&quot;) -&gt; CostFn</code></td><td>per-executor pricing, calibrated to a target profile</td></tr><tr><td>fused</td><td><code>fused_cost_for(profile=None) -&gt; CostFn</code></td><td>fusion-aware pricing</td></tr><tr><td>lowering-aware</td><td><code>lowering_aware_cost_for(profile=None, *, lowerings=LOWERINGS, base=&quot;roofline&quot;) -&gt; CostFn</code></td><td>prices across the <code>LOWERINGS</code> family (<code>(&quot;generic&quot;, &quot;batched_scan&quot;, &quot;compiled&quot;)</code>)</td></tr><tr><td>depth / roofline</td><td><code>depth_cost</code>, <code>depth_cost_for(profile=None)</code>; <code>roofline_cost</code>, <code>roofline_cost_for(profile=None, *, peak_flops=None, peak_bw=None, launch_s=None)</code></td><td>critical-path and roofline pricing</td></tr><tr><td>launch</td><td><code>launch_aware_cost(term, memo=None)</code></td><td>launch-overhead pricing</td></tr><tr><td>fusion regions</td><td><code>fusion_regions(term, memo=None) -&gt; tuple[frozenset, ...]</code>, <code>fusion_member_key(term, memo=None) -&gt; tuple[int, int]</code></td><td>the fusible-partition analysis the fused models price over</td></tr><tr><td>configurable</td><td><code>CostModel(op_weights=None, weight_coeff=1.0, matmul_coeff=2.0)</code></td><td>a callable weighted-FLOPs model for <code>EGraph.extract_best</code></td></tr></tbody></table><p>The <code>_for</code> family are <em>factories</em> — they return a <code>CostFn</code> bound to a target profile or lowering; the bare names are ready-made cost fns. A <code>profile</code> is a <code>mlopt_core.profile.TargetProfile</code>-like object or dict; <code>None</code> is the built-in profile.</p><h2 id="what-a-cost-can-and-cannot-say" tabindex="-1">What a cost can and cannot say <a class="header-anchor" href="#what-a-cost-can-and-cannot-say" aria-label="Permalink to “What a cost can and cannot say”">​</a></h2><p><code>dag_cost</code> ranking says &quot;probably cheaper&quot; — it has no notion of memory traffic, kernel fusion, or launch overhead (a fused <code>sdpa</code> looks expensive on paper and is fast under Inductor). Measured pay and the certificate are the domain side&#39;s job — see <a href="/docs/graphopt/explanation/three-costs.html">the three costs</a>.</p><p>Source: <a href="https://github.com/handl-lang/eqsat/tree/main/packages/mlopt-core/src/mlopt_core/cost" target="_blank" rel="noreferrer"><code>mlopt_core/cost/</code></a>.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};